@page "/dashboard"
@using sv_bf7bd866056d42e0af8b9311c767ccbf.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard — @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-header">
        <strong>Current Warehouse:</strong> @WarehouseState.CurrentWarehouseName
        <span class="text-muted">(@WarehouseState.CurrentWarehouseId)</span>
    </div>
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="display-4">
            @if (_alertCount > 0)
            {
                <span class="text-danger">⚠️ @_alertCount items below minimum</span>
            }
            else
            {
                <span class="text-success">✅ All stock levels OK</span>
            }
        </p>
        <p class="text-muted">
            Polling every 10 seconds. Last updated: @_lastUpdated.ToString("HH:mm:ss")
        </p>
    </div>
</div>

<div class="card">
    <div class="card-header">How This Works</div>
    <div class="card-body">
        <ul>
            <li>The <strong>WarehouseSelector</strong> in the top bar shares state via a scoped <code>WarehouseStateService</code>.</li>
            <li>The <strong>AlertBadge</strong> in the sidebar and this dashboard both subscribe to <code>InventoryAlertService.OnAlertCountChanged</code>.</li>
            <li>Polling starts when this page loads and stops when you navigate away.</li>
            <li>Changing the warehouse immediately triggers a fresh alert check for the new site.</li>
            <li>Each browser circuit gets its own scoped service instances — users are fully isolated.</li>
        </ul>
    </div>
</div>

@code {
    private int _alertCount;
    private DateTime _lastUpdated = DateTime.Now;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleWarehouseChanged;
        AlertService.OnAlertCountChanged += HandleAlertChanged;

        // Start polling — this page owns the polling lifecycle
        AlertService.StartPolling();

        _alertCount = AlertService.CurrentAlertCount;
    }

    private void HandleWarehouseChanged() => InvokeAsync(StateHasChanged);

    private async Task HandleAlertChanged()
    {
        _alertCount = AlertService.CurrentAlertCount;
        _lastUpdated = DateTime.Now;
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleWarehouseChanged;
        AlertService.OnAlertCountChanged -= HandleAlertChanged;
        AlertService.StopPolling();
    }
}

